local snippets = {}

for n = 1, #vulkan_structs do
    local spec = vulkan_structs[n]
    local trigger = spec[1]
    local field_count = spec[2]
    local structure_type = spec[3]
    local nodes = {}

    if structure_type then
        nodes[1] = text({ "{", "    " .. structure_type .. ",", "    " })
    else
        nodes[1] = text({ "{", "    " })
    end

    local node_index = 2
    for field = 1, field_count do
        nodes[node_index] = insert(field, "{}")
        node_index = node_index + 1

        if field == field_count then
            nodes[node_index] = text({ ",", "}" })
        else
            nodes[node_index] = text({ ",", "    " })
        end
        node_index = node_index + 1
    end

    snippets[n] = snippet(trigger, nodes)
end

return snippets
